import random, itertools, collections, math, time
n=15
all_edges=[(i,j) for i in range(n) for j in range(i+1,n)]

def girth_ok(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # check no cycles <=6: for each edge remove and compute distance <=5 between ends? cycle length dist+1<=6
    for u,v in edges:
        # bfs u to v without edge, max depth 5
        seen={u}; q=collections.deque([(u,0)])
        while q:
            x,d=q.popleft()
            if d>=5: continue
            for y in adj[x]:
                if (x==u and y==v) or (x==v and y==u): # only removes edge? direction from u maybe
                    continue
                if (x==v and y==u): continue
                # easier skip if {x,y}=={u,v}
                if (x==u and y==v) or (x==v and y==u): continue
                if y==v:
                    return False
                if y not in seen:
                    seen.add(y); q.append((y,d+1))
    return True

def can_add(edge, adj):
    # distance between endpoints in current graph must be >=6 or nonexistent, because new edge creates cycle len dist+1; avoid <=6 => dist>=6
    u,v=edge
    seen={u}; q=collections.deque([(u,0)])
    while q:
        x,d=q.popleft()
        if d>=5: continue
        for y in adj[x]:
            if y==v:
                return False
            if y not in seen:
                seen.add(y); q.append((y,d+1))
    return True

# random maximal greedy multiple attempts
best=[]
bestadj=None
start=time.time()
for t in range(10000):
    order=all_edges[:]
    random.shuffle(order)
    adj=[set() for _ in range(n)]
    edges=[]
    for e in order:
        if can_add(e,adj):
            u,v=e; edges.append(e); adj[u].add(v); adj[v].add(u)
    if len(edges)>len(best):
        best=edges[:]; bestadj=[s.copy() for s in adj]
        print('best', len(best), best, 'degrees', sorted([len(s) for s in adj], reverse=True), 'time', time.time()-start)
        if len(best)>=22: break
print('final', len(best), best, girth_ok(best))
